-- EvalOtter seed data — generated by scripts/seed/generate-sql.ts
-- Equivalent to `npm run seed`. Idempotent: safe to re-run.
-- 29 assessments from scripts/seed/data/*.json
-- Run AFTER the schema migrations (supabase/combined_migrations.sql).
-- full-iq-estimation-report — file 13 of 29. Self-contained: its
-- category, its own questions, then the assessment itself.
-- Safe to re-run on its own.

begin;
insert into assessment_categories (key, label, icon, "order") values ('ai-analysis', 'AI Analysis', 'sparkles', 10)
  on conflict (key) do update set label = excluded.label, icon = excluded.icon, "order" = excluded."order";

insert into questions (external_key, question_type, question_text, instructions, media, correct_answer, score_config, difficulty, category, tags, time_limit_seconds, required) values ('fier-ack-01', ('multiple_choice')::question_type, 'This report reads your existing Brain Profile results rather than asking new questions. Ready to generate your composite estimate?', NULL, ('[]')::jsonb, NULL, ('[]')::jsonb, ('easy')::assessment_difficulty, 'full-iq-estimation-report', '{}'::text[], NULL, true)
  on conflict (external_key) do update set question_type = excluded.question_type, question_text = excluded.question_text, instructions = excluded.instructions, media = excluded.media, correct_answer = excluded.correct_answer, score_config = excluded.score_config, difficulty = excluded.difficulty, category = excluded.category, tags = excluded.tags, time_limit_seconds = excluded.time_limit_seconds, required = excluded.required;
delete from question_options where question_id = (select id from questions where external_key = 'fier-ack-01');
insert into question_options (question_id, label, value, image_url, is_correct, "order", score_config) values
  ((select id from questions where external_key = 'fier-ack-01'), 'Yes, generate my composite estimate', '0', NULL, NULL, 0, ('[]')::jsonb),
  ((select id from questions where external_key = 'fier-ack-01'), 'I understand this is an estimate, not a clinical score', '1', NULL, NULL, 1, ('[]')::jsonb);

-- full-iq-estimation-report (full-iq-estimation-report.json)
insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('full-iq-estimation-report', 'Full IQ Estimation Report', 'A comprehensive, multi-battery composite drawing on every completed assessment to estimate a full-scale IQ range.', 'Full IQ Estimation Report doesn''t ask its own questions — it computes a composite from the Logical, Verbal, Spatial, and Memory scores in your existing Brain Profile, the same four cognitive-ability domains real full-scale IQ batteries combine (e.g. the WAIS''s Verbal Comprehension, Perceptual Reasoning, Working Memory, and Processing Speed indices). Emotional Intelligence and Creative scores are deliberately excluded from this composite, the same way Palmistry is excluded from the Brain Profile aggregate — they measure real things, just not what "IQ" traditionally refers to.', 'file-text', (select id from assessment_categories where key = 'ai-analysis'), ('ai_analysis')::assessment_engine_type, ('hard')::assessment_difficulty, 45, 1, false, ('premium')::assessment_access, ('published')::assessment_status)
  on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, long_description = excluded.long_description, icon = excluded.icon, category_id = excluded.category_id, engine_type = excluded.engine_type, difficulty = excluded.difficulty, estimated_duration_minutes = excluded.estimated_duration_minutes, question_count = excluded.question_count, featured = excluded.featured, access = excluded.access, status = excluded.status;
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'full-iq-estimation-report'), 'iq-composite', 'Full-Scale Composite Estimate', 'Average of your Logical, Verbal, Spatial, and Memory Brain Profile scores — not scored from a new test.', false, NULL, 1)
  on conflict (assessment_id, key) do update set label = excluded.label, description = excluded.description, contributes_to_brain_profile = excluded.contributes_to_brain_profile, brain_profile_dimension_key = excluded.brain_profile_dimension_key, "order" = excluded."order";
delete from result_ranges where assessment_id = (select id from assessments where slug = 'full-iq-estimation-report');
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'full-iq-estimation-report'), 'overall', 0, 5, 'Not Enough Data Yet', 'You haven''t completed enough of the four core assessments (Logical Reasoning or Abstract Reasoning Pro or Fluid Intelligence Peak, Verbal Reasoning or Verbal Intelligence, Spatial Intelligence or Visuospatial Rotation, Memory Recall) for a meaningful composite. Complete at least 3 of those 4 domains, then come back.', ARRAY['Complete at least one assessment in each of the Logical, Verbal, Spatial, and Memory categories', 'The more of the ten-plus assessments in each domain you complete, the more stable this composite becomes', 'This report re-checks your data every time you take it — no need to "reset" anything']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'full-iq-estimation-report'), 'overall', 6, 30, 'Estimated range: below 90', 'Based on your completed assessments across the four core domains. Remember this is a self-reflection estimate, not a clinically validated IQ score — this platform has no standardization sample behind it.', ARRAY['Look at your Brain Profile page for which specific domain is pulling the composite down', 'Complete more assessments in your weaker domain(s) — this composite updates automatically as you do']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'full-iq-estimation-report'), 'overall', 31, 50, 'Estimated range: 90-100', 'Based on your completed assessments across the four core domains — an estimate for self-reflection, not a clinically validated score.', ARRAY['Check your Brain Profile for your strongest and weakest of the four core domains', 'Retaking assessments you''ve improved on since your first attempt will refresh this composite']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'full-iq-estimation-report'), 'overall', 51, 70, 'Estimated range: 100-115', 'Based on your completed assessments across the four core domains — an estimate for self-reflection, not a clinically validated score.', ARRAY['This composite reflects fairly balanced performance across Logical, Verbal, Spatial, and Memory', 'Consider Fluid Intelligence Peak or Verbal Reasoning Mastery if you want to stress-test your ceiling in a specific domain']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'full-iq-estimation-report'), 'overall', 71, 85, 'Estimated range: 115-130', 'Based on your completed assessments across the four core domains — an estimate for self-reflection, not a clinically validated score.', ARRAY['A strong composite across all four domains — check your Brain Profile to see if one domain leads the others', 'For an actual clinical or professionally normed IQ score, a licensed psychologist administering a standardized instrument is the real route — this report doesn''t replace that']::text[], NULL, 5);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'full-iq-estimation-report'), 'overall', 86, 100, 'Estimated range: 130+', 'Based on your completed assessments across the four core domains — an estimate for self-reflection, not a clinically validated score.', ARRAY['An exceptional composite across Logical, Verbal, Spatial, and Memory domains', 'As with any tier here: this is a self-assessment composite, not a substitute for a professionally administered, normed IQ test']::text[], NULL, 6);
delete from brain_profile_contribution_rules where assessment_id = (select id from assessments where slug = 'full-iq-estimation-report');
insert into assessment_versions (assessment_id, version_number, status, settings, published_at)
  select a.id, coalesce((select max(v.version_number) from assessment_versions v where v.assessment_id = a.id), 0) + 1, 'published'::assessment_status, ('{"allowBackNavigation":true,"randomizeSections":false,"randomizeQuestions":false,"randomizeAnswerOrder":false,"showProgressBar":true,"showInstructionsBetweenSections":true,"autosaveIntervalSeconds":10,"totalTimeLimitSeconds":null}')::jsonb, now()
  from assessments a where a.slug = 'full-iq-estimation-report';
update assessments set current_version_id = (select v.id from assessment_versions v where v.assessment_id = assessments.id order by v.version_number desc limit 1) where slug = 'full-iq-estimation-report';
insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values ((select current_version_id from assessments where slug = 'full-iq-estimation-report'), 'Before You Continue', 'A one-step confirmation before generating your composite.', 'This isn''t a new test — it reads your existing results.', NULL, false, 1, 1);
insert into scoring_rules (assessment_version_id, dimension_key, formula, section_weights, normalization, penalty_per_incorrect) values ((select current_version_id from assessments where slug = 'full-iq-estimation-report'), 'iq-composite', ('custom')::scoring_formula, NULL, NULL, NULL);
insert into assessment_questions (assessment_version_id, section_id, question_id, "order", weight) values
  ((select current_version_id from assessments where slug = 'full-iq-estimation-report'), (select id from assessment_sections where assessment_version_id = (select current_version_id from assessments where slug = 'full-iq-estimation-report') and name = 'Before You Continue'), (select id from questions where external_key = 'fier-ack-01'), 1, 1);
commit;
